&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;GMP &amp;amp; fabrication audits, checking &amp;amp; reporting adherence to Quality Management policies &amp;amp; procedures&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Glass &amp;amp; Brittle Plastic Audits&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Inspect daily supplier deliveries: pallets, documentation, labelling accuracy, packaging integrity&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Take samples and conduct testing (Near Infra-Red Spectrometer, organoleptic checks)&lt;/span&gt;&lt;/li&gt;
